INSERT INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score, created_at, google_place_id, category, cuisine, price_band, veg_flag, source, updated_at, verification_status, verification_notes, verified_at) VALUES
('200021', '2002', 'Phuket Old Town', 'Phuket Old Town', 'Historic Phuket Town quarter of Sino-European shophouses, shrines, street art, cafés and Baba-Peranakan heritage.', '2-4 hours', 'Late Afternoon', 'Walk Thalang, Dibuk, Phang Nga, Yaowarat and Krabi roads; Sunday is best if you also want the walking street.', '', 'Phuket', 0, 0, '', '', 'Free public district; food, museums and shopping extra', 4.9, 4.7, 7.8849, 98.3889, 'Thalang Road and surrounding streets, Talat Yai/Talat Nuea, Mueang Phuket, Phuket 83000', 'https://www.tourismthailand.org/Attraction/phuket-old-town', 0.96, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'Tourism Authority of Thailand and Phuket provincial material confirm Old Town across Thalang, Dibuk, Phang Nga, Yaowarat, Krabi and Soi Romanee, with preserved Sino-European architecture and Baba-Peranakan culture. Public streets have no single gate or admission schedule.', '2026-10-01'),
('200022', '2002', 'Phuket Thai Hua Museum', 'Phuket Thai Hua Museum', 'Museum in a historic Chinese-school building explaining Hokkien migration, tin mining and Phuket Baba-Peranakan culture.', '1-2 hours', 'Afternoon', 'Visit before walking Krabi Road and nearby heritage mansions.', '', 'Phuket', 0, 0, '', '', 'Foreign adults THB 200; children THB 120 per TAT provincial e-brochure', 4.5, 4.4, 7.8856, 98.3867, '28 Krabi Road, Talat Nuea, Mueang Phuket, Phuket 83000', NULL, 0.83, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'TAT Phuket provincial e-brochure lists daily 9:00 AM-5:00 PM and admission THB 200 adult / THB 120 child. The museum is also included in current TAT Phuket itineraries. A live official museum website was not relied on in this pass.', '2026-10-01'),
('200023', '2002', 'Chinpracha House Museum', 'Baan Chinpracha', 'Early-20th-century Sino-Portuguese mansion preserving family furniture, tiled floors and a traditional internal courtyard.', '45-60 minutes', 'Morning', 'Pair it with Thai Hua Museum and Blue Elephant on the same Krabi Road heritage walk.', '', 'Phuket', 0, 0, '', '', 'Reported THB 150 adult / THB 75 child; verify at entrance', 4.3, 4.3, 7.8858, 98.3840, '98 Krabi Road, Talat Nuea, Mueang Phuket, Phuket 83000', NULL, 0.77, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'partial', 'TAT includes Baan Chinpracha in Phuket heritage itineraries. Current travel listings converge around 9:00 AM-4:30 PM; one government tourism-directory rendering exposes malformed hours, so schedule and admission are marked partial. Admission commonly reported THB 150 adult / THB 75 child.', '2026-10-01'),
('200024', '2002', 'Wat Chai Thararam (Wat Chalong)', 'Wat Chalong', 'Phuket’s best-known Buddhist temple, associated with revered monks Luang Pho Chaem and Luang Pho Chuang.', '1-2 hours', 'Morning', 'Dress respectfully and combine with Big Buddha and the southern viewpoints.', '', 'Phuket', 0, 0, '', '', 'Free entry; donations optional', 4.9, 4.8, 7.8463, 98.3371, 'Chao Fa West Road, Chalong, Mueang Phuket, Phuket 83000', 'https://www.wat-chalong-phuket.com/index.html', 0.95, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'Tourism Authority of Thailand Japan lists Wat Chalong 8:00 AM-5:00 PM with free admission. TAT Thailand also identifies it as a major Phuket faith and heritage site.', '2026-10-01'),
('200025', '2002', 'Wat Kittisangharam (Big Buddha)', 'Phuket Big Buddha', 'Hilltop religious site centered on Phuket’s 45-metre white Buddha image with wide views over southern Phuket.', '1-2 hours', 'Morning', 'Use the approved public area only and follow onsite access controls; conditions can change during heavy rain.', '', 'Phuket', 1, 1, '6:30 AM', '6:15 PM', 'No commercial admission reported; donations support temple operations', 4.8, 4.6, 7.8278, 98.3128, 'Nakkerd Hill, Karon, Mueang Phuket, Phuket', NULL, 0.9, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'partial', 'The site reopened 3 Mar 2026 after the 2024 landslide closure, under Wat Kittisangharam management and Royal Forest Department conditions. Current reported hours are 9:00 AM-6:00 PM. Legal/environmental disputes connected to the 2024 landslide remain unresolved, so status should be refreshed before publication.', '2026-10-01'),
('200026', '2002', 'Karon Viewpoint', 'Three Bays Viewpoint', 'Roadside viewpoint overlooking Kata Noi, Kata and Karon beaches in one sweeping Andaman Sea panorama.', '20-40 minutes', 'Morning', 'Stop here while driving between Kata and Nai Harn; morning usually gives clearer views and fewer crowds.', '', 'Phuket', 1, 1, '6:30 AM', '6:15 PM', 'Free', 4.7, 4.6, 7.7973, 98.3021, 'Route 4233, Karon, Mueang Phuket, Phuket 83100', 'https://www.tourismthailand.org/Attraction/karon-viewpoint', 0.88, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'partial', 'TAT confirms the Three Bays viewpoint and the visible Kata Noi/Kata/Karon bays. Current local listings consistently describe the roadside viewpoint as free and open 24 hours; TAT does not expose a usable daily timetable on the fetched page.', '2026-10-01'),
('200027', '2002', 'Promthep Cape', 'Laem Phromthep', 'Phuket’s famous southern cape and sunset viewpoint with lighthouse-area panoramas over the Andaman Sea.', '1 hour', 'Sunset', 'Arrive at least 45 minutes before sunset because the main terrace gets crowded.', '', 'Phuket', 1, 1, '6:30 AM', '6:15 PM', 'Free', 4.8, 4.7, 7.7590, 98.3033, 'Rawai, Mueang Phuket, Phuket 83130', NULL, 0.93, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'partial', 'TAT names Laem Phromthep among Phuket’s signature viewpoints and highlights its sunsets. Current mapping/local sources list the public viewpoint as open 24 hours and free; no authoritative gate schedule was found because it is an open cape/viewpoint.', '2026-10-01'),
('200028', '2002', 'Patong Beach', 'Patong Beach', 'Phuket’s busiest resort beach, with a broad sandy bay, water activities, shopping and nightlife nearby.', '2-4 hours', 'Morning', 'For swimming, follow lifeguard flags; red flags are common during rough monsoon conditions.', '', 'Phuket', 1, 1, '6:30 AM', '6:15 PM', 'Free public beach; activities extra', 4.7, 4.4, 7.8957, 98.2953, 'Thaweewong Road, Pa Tong, Kathu, Phuket 83150', NULL, 0.89, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'partial', 'TAT identifies Patong as one of Phuket’s major beaches and marine-activity hubs. It is a public beach without a single published opening/closing schedule; swimming safety depends on sea conditions and flags.', '2026-10-01'),
('200029', '2002', 'Kata Beach', 'Kata Beach', 'Popular west-coast beach with a curved bay, seasonal surf, swimming in calmer months and views toward Ko Pu.', '2-4 hours', 'Morning', 'Surf is more active in the southwest monsoon; in any season, obey warning flags.', '', 'Phuket', 1, 1, '6:30 AM', '6:15 PM', 'Free public beach; rentals and lessons extra', 4.7, 4.6, 7.8204, 98.2988, 'Kata, Karon, Mueang Phuket, Phuket 83100', 'https://thai.tourismthailand.org/Attraction/%E0%B8%AB%E0%B8%B2%E0%B8%94%E0%B8%81%E0%B8%B0%E0%B8%95%E0%B8%B0', 0.9, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'TAT confirms Kata Beach as a swimming and dive-training beach with reef areas toward Ko Pu. As an open public beach it has no formal ticketed visitor schedule.', '2026-10-01'),
('200030', '2002', 'Karon Beach', 'Karon Beach', 'Long west-coast beach between Patong and Kata, known for its broad sand and more open, spacious shoreline.', '2-4 hours', 'Morning', 'The beach is exposed to seasonal currents; swim only when flags and lifeguard guidance allow.', '', 'Phuket', 1, 1, '6:30 AM', '6:15 PM', 'Free public beach; activities extra', 4.6, 4.5, 7.8426, 98.2938, 'Karon, Mueang Phuket, Phuket 83100', NULL, 0.87, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'partial', 'TAT lists Karon among Phuket’s major beaches. No controlled visitor gate or authoritative daily opening schedule applies; current location data places the beach around 7.8426, 98.2938.', '2026-10-01'),
('200031', '2002', 'Nai Harn Beach', 'Nai Harn Beach', 'Scenic southern Phuket bay backed by green hills and a freshwater lake, popular for swimming in the calmer season.', '2-4 hours', 'Morning', 'Combine with Windmill Viewpoint and Promthep Cape; check flags during monsoon months.', '', 'Phuket', 1, 1, '6:30 AM', '6:15 PM', 'Free public beach', 4.7, 4.7, 7.7765, 98.3054, 'Rawai, Mueang Phuket, Phuket 83130', NULL, 0.89, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'partial', 'TAT identifies Nai Harn as one of Phuket’s major beaches. It is open-access rather than a ticketed attraction; no authoritative daily gate schedule was found.', '2026-10-01'),
('200032', '2002', 'Phuket Aquarium', 'Phuket Aquarium', 'Government marine aquarium at Cape Panwa presenting local marine ecosystems, reef species and ocean education.', '1-2 hours', 'Afternoon', 'A useful indoor option during heavy rain; arrive before the 4:00 PM ticket cutoff.', '', 'Phuket', 0, 0, '', '', 'Foreign adult THB 300; child THB 150; under 108 cm free', 4.4, 4.3, 7.8035, 98.4079, '51 Moo 8 Sakdidej Road, Wichit, Mueang Phuket, Phuket 83000', 'https://phuketaquarium.org/', 0.8, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'Official Phuket Aquarium site lists daily opening 8:30 AM-4:30 PM with ticket sales closing 4:00 PM. Official foreign admission: THB 300 adult, THB 150 child, free under 108 cm.', '2026-10-01'),
('200033', '2002', 'Phuket Elephant Sanctuary', 'Phuket Elephant Sanctuary', 'Observation-focused sanctuary in Paklok where rescued elephants roam in forest habitat, with an elephant hospital and canopy walkway.', '3.5 hours', 'Morning', 'Book ahead, especially November-April; visitors meet at the Paklok office and transfer into the sanctuary.', 'Advance booking required', 'Phuket', 0, 0, '', '', 'Half-day program from THB 3,000 adult; Canopy Walkway from THB 1,900', 4.8, 4.8, 8.0260, 98.4015, '100 Moo 2, Paklok, Thalang, Phuket 83110', 'https://www.phuketelephantsanctuary.org/', 0.94, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'premium', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'Official sanctuary site checked 2026-10-01: half-day sessions 9:30 AM-1:00 PM and 1:30-5:00 PM, from THB 3,000 adult; canopy walkway programs from THB 1,900. Sanctuary states it is observation-focused and discontinued feeding interactions from Apr 2026.', '2026-10-01'),
('200034', '2002', 'Gibbon Rehabilitation Project', 'Gibbon Rehabilitation Project', 'Wildlife rehabilitation project near Bang Pae focused on rescuing and reintroducing gibbons while educating visitors about wildlife protection.', '1-2.5 hours', 'Morning', 'Visits are booking-only; do not arrive without a confirmed learning session because the project can be closed when no sessions are scheduled.', 'Advance booking required', 'Phuket', 0, 0, '', '', '1-hour learning program listed at THB 1,100; longer programs vary', 4.6, 4.7, 8.0412, 98.3931, '104/3 Moo 3, Paklok, Thalang, Phuket 83110', 'https://www.gibbonproject.org/visit-us/booking/', 0.84, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'mid', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'Official Gibbon Rehabilitation Project says visits are available only through learning-session bookings and the site may remain closed on days without bookings. 1-hour sessions are 10:30-11:30, 12:30-1:30 and 2:00-3:00; 2.5-hour morning program 9:30-12:00. Current 1-hour shop listing shows THB 1,100.', '2026-10-01'),
('200035', '2002', 'Sirinat National Park', 'Sirinat National Park', 'Marine national park on Phuket’s northwest coast protecting beaches, casuarina forest, coral habitat and sea-turtle nesting areas.', '2-4 hours', 'Morning', 'Good first/last-day stop near the airport; keep the park ticket if moving between park sections.', '', 'Phuket', 1, 1, '6:30 AM', '6:15 PM', 'Foreign adult THB 200; foreign child THB 100', 4.5, 4.5, 8.0955, 98.2977, '89/1 Moo 1, Sakhu, Thalang, Phuket 83110', 'https://www.tourismthailand.org/Attraction/sirinat-national-park', 0.84, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'partial', 'TAT official page confirms Sirinat National Park and foreign admission THB 200 adult / THB 100 child. Current 2026 visitor listings consistently report 6:00 AM-6:00 PM; the fetched TAT page did not expose readable hours, so schedule is marked partial.', '2026-10-01'),
('200036', '2002', 'Phuket Sunday Walking Street (Lard Yai)', 'Lard Yai Market', 'Weekly Sunday walking street on Thalang Road with Phuket street food, crafts, music and Old Town heritage scenery.', '2-3 hours', 'Evening', 'Arrive around 4:30-5:00 PM before the densest crowds and stay into the evening for food and performances.', '', 'Phuket', 0, 0, '', '', 'Free entry; vendor purchases extra', 4.7, 4.6, 7.8848, 98.3880, 'Thalang Road, Phuket Old Town, Mueang Phuket, Phuket 83000', NULL, 0.88, '2026-10-01 16:22:00', NULL, 'attraction', 'Street Food', 'budget', 'veg-options', 'own', '2026-10-01 16:22:00', 'verified', 'TAT current Phuket itinerary states the walking street is held every Sunday from 4:00 PM-10:00 PM along Thalang Road. It is locally called Lard Yai.', '2026-10-01'),
('200037', '2002', 'Blue Elephant Phuket', 'Blue Elephant Phuket', 'Upscale Thai heritage restaurant and cooking school in the restored Phra Pitak Chinpracha governor’s mansion.', '1.5-2 hours', 'Evening', 'Reserve for dinner or book a cooking class separately; the historic mansion is part of the experience.', 'Reservation recommended', 'Phuket', 0, 0, '', '', 'À la carte premium pricing; cooking-school programs priced separately', 4.6, 4.5, 7.8861, 98.3842, '96 Krabi Road, Talat Nuea, Mueang Phuket, Phuket 83000', 'https://blueelephant.com/restaurant/phuket-restaurant/', 0.84, '2026-10-01 16:22:00', NULL, 'restaurant', 'Thai / Southern Thai', 'premium', 'veg-options', 'own', '2026-10-01 16:22:00', 'verified', 'Official Blue Elephant Phuket page checked 2026-10-01: address 96 Krabi Road; opening Mon-Sun 9:00 AM-10:30 PM. Restaurant presents Phuketian/Peranakan and broader Thai heritage cooking.', '2026-10-01'),
('200038', '2002', 'Mor Mu Dong', 'Mor Mu Dong', 'Local southern Thai restaurant in the Chalong mangroves known for seafood and Phuket-style dishes in rustic private huts.', '1-2 hours', 'Afternoon', 'Go by car/taxi; the setting is tucked away from the main tourist roads and advance reservations are generally not offered.', '', 'Phuket', 0, 0, '', '', 'Thailand tourism directory price range THB 101-250', 4.6, 4.5, 7.8431, 98.3720, '9/4 Moo 3, Soi Palai, Chalong, Mueang Phuket, Phuket 83000', NULL, 0.83, '2026-10-01 16:22:00', NULL, 'restaurant', 'Southern Thai / Seafood', 'mid', 'veg-options', 'own', '2026-10-01 16:22:00', 'partial', 'Thailand Digital Tourism Center confirms Mor Mu Dong in Chalong, southern-food category and THB 101-250 price range, but its displayed hours appear timezone-shifted/malformed. Current local listings place service around late morning through evening, so exact hours remain partial.', '2026-10-01'),
('200039', '2002', 'One Chun Cafe & Restaurant', 'One Chun', 'Popular Phuket Old Town restaurant serving Southern Thai and Phuket family recipes in a vintage Sino-Portuguese building.', '1-2 hours', 'Afternoon', 'Expect queues at peak lunch and dinner; signature dishes include Phuket-style pork and crab preparations.', '', 'Phuket', 0, 0, '', '', 'Mid-range; MICHELIN price category ฿฿', 4.7, 4.6, 7.8858, 98.3907, '48/1 Thep Krasatti Road, Talat Yai, Mueang Phuket, Phuket 83000', NULL, 0.86, '2026-10-01 16:22:00', NULL, 'restaurant', 'Southern Thai', 'mid', 'veg-options', 'own', '2026-10-01 16:22:00', 'verified', 'MICHELIN Guide lists One Chun at 48/1 Thep Krasatti Road, Southern Thai cuisine, price category ฿฿ and daily service around 10:00 AM-10:00 PM. The restaurant’s current social-link page also states daily 10:00 AM-10:00 PM.', '2026-10-01'),
('200040', '2002', 'Raya Restaurant', 'Raya', 'Long-running Phuket restaurant in a heritage house serving local and Southern Thai specialties such as crab curry, moo hong and shrimp-paste relishes.', '1-2 hours', 'Evening', 'Reserve at busy periods; it is close to One Chun but represents a separate classic Phuket dining institution.', 'Reservation recommended', 'Phuket', 0, 0, '', '', 'Mid to premium local dining; menu prices vary by dish', 4.7, 4.6, 7.8858, 98.3910, '48/1 Dibuk Road, Talat Yai, Mueang Phuket, Phuket 83000', 'https://www.rayarestaurant.net/', 0.86, '2026-10-01 16:22:00', NULL, 'restaurant', 'Phuket / Southern Thai', 'mid', 'veg-options', 'own', '2026-10-01 16:22:00', 'verified', 'Official Raya website checked 2026-10-01: 48/1 Dibuk Road, open daily 10:00 AM-10:00 PM with last order 9:30 PM.', '2026-10-01');
